def score(model, weights):
    # weights let a step say what it cares about
    return (weights["q"] * model["quality"]
            + weights["s"] * model["speed"]
            - weights["c"] * model["cost"])

latency_first = {"q": 1, "s": 3, "c": 1}
quality_first = {"q": 3, "s": 1, "c": 1}
# same models, different winner depending on the step's priorities
print("latency step wants:", score(MODELS_small := {"quality":3,"speed":5,"cost":1}, latency_first))
# the triangle: you optimize for the dial the step cares about

def supports_agent_features(model_caps: dict) -> bool:
    # an agent needs BOTH to run the loop reliably
    return model_caps.get("tool_calling") and model_caps.get("structured_output")

caps = {"tool_calling": True, "structured_output": False}
if not supports_agent_features(caps):
    print("model can't reliably emit tool args -> not agent-ready")
# capability, not just price, decides whether a model can drive your loop

def route(task, run):
    # try the cheap model first, verify, fall back if it fails
    answer = run("small", task)
    if not passes_quality_check(answer):
        answer = run("frontier", task)  # fallback to a stronger tier
    return answer

def passes_quality_check(answer) -> bool:
    return answer is not None and answer.get("confident", False)
